/*Node 2: Check if `The Crop Yield is not affected by the Region` (opt1) was selected*/
opt1_selected: if member(1, ans1) then 1 else 0;

/*Node 3: Check if `The Crop Yield is not affected by the Crop Type` (opt2) was selected*/
opt2_selected: if member(2, ans1) then 1 else 0;

/*Node 4: Check if `In the North Region, the Sorghum crop tends to result in the highest yield of the three crops` (opt3) was selected*/
opt3_selected: if member(3, ans1) then 1 else 0;

/*Node 5: Check if `In the North Region, the Soil Quality Index Score is always correlated with the Crop Yield regardless of Crop` (opt4) was selected*/
opt4_selected: if member(4, ans1) then 1 else 0;

/*Node 6: Check if `In the South Region, the Corn and Rice crop tend to result in the highest yield` (opt5) was selected*/
opt5_selected: if member(5, ans1) then 1 else 0;

/*Node 7: Check if `Corn and Rice are impacted the same way as the region moves from North to South` (opt6) was selected*/
opt6_selected: if member(6, ans1) then 1 else 0;

/*Node 8: Check if `The Soil Quality Index Score is not correlated with the Crop Yield for Sorghum in the South Region` (opt7) was selected*/
opt7_selected: if member(7, ans1) then 1 else 0;
